using System;using System.IO;using System.Linq;using System.Reflection;using System.Collections.Generic;using System.Diagnostics;using System.Drawing;using System.Drawing.Imaging;using System.Text;using System.Windows.Forms;
class MarkerReviewChecks {
 static BindingFlags st=BindingFlags.Static|BindingFlags.NonPublic|BindingFlags.Public,ins=BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public;static Assembly asm;static int checks;
 static object Call(Type t,string n,params object[]a){try{return t.GetMethod(n,st).Invoke(null,a);}catch(TargetInvocationException e){throw e.InnerException;}}
 static object F(object o,string n){return o.GetType().GetField(n,ins).GetValue(o);}
 static object Invoke(object o,string n,params object[]a){try{return o.GetType().GetMethod(n,ins).Invoke(o,a);}catch(TargetInvocationException e){throw e.InnerException;}}
 static void Check(bool ok,string text){if(!ok)throw new Exception(text);checks++;Console.WriteLine("PASS "+text);}
 static Control Find(Control c,string name){return c.Controls.Find(name,true).First();}
 static string[] keys={"HighCoreCPUFix","FixInputHistory","FixSolarArrayElevator","FixMenuSpeed","FixExplosionDamage","FixOffscreenEffects"};
 static int Index(CheckedListBox list,string key){for(int i=0;i<list.Items.Count;i++)if((string)list.Items[i].GetType().GetProperty("Key").GetValue(list.Items[i],null)==key)return i;throw new Exception(key);}
 static bool Review(Form form,string output,string language,bool accept,bool clearAll=false){var initialList=(CheckedListBox)F(form,"markerOptionsList");var initial=Enumerable.Range(0,initialList.Items.Count).Select(initialList.GetItemChecked).ToArray();Exception failure=null;bool seen=false,early=false,late=false,toggled=false,captured=false;var watch=Stopwatch.StartNew();using(var timer=new System.Windows.Forms.Timer { Interval=50 }){
 timer.Tick+=(s,e)=>{try{Form dialog=Application.OpenForms.Cast<Form>().FirstOrDefault(x=>x.Name=="markerInstallReviewDialog");if(dialog==null){if(watch.Elapsed.TotalSeconds>8)throw new Exception("Review did not open");return;}var yes=(Button)Find(dialog,"markerReviewAccept");var no=(Button)Find(dialog,"markerReviewDecline");var optional=(CheckBox)Find(dialog,"markerReviewFeatures");var list=(CheckedListBox)F(form,"markerOptionsList");
 if(!seen){seen=true;Check(!yes.Enabled,"confirmation initially disabled "+language);Check(no.Enabled,"return remains available "+language);Check(no.Text==(language=="en"?"Cancel and return":"取消并返回"),"cancel caption explains return action "+language);string notice=Find(dialog,"markerReviewNotice").Text;Check(notice.Contains(language=="en"?"compatibility":"兼容性"),"compatibility notice translated "+language);Check(yes.Bottom<=dialog.ClientSize.Height&&no.Bottom<=dialog.ClientSize.Height,"confirmation controls fit "+language);}
 if(!accept){no.PerformClick();timer.Stop();return;}
 if(!toggled){optional.Checked=false;Check(keys.All(k=>!list.GetItemChecked(Index(list,k))),"DLC-only hides optional fix selections "+language);optional.Checked=true;Check(Enumerable.Range(0,list.Items.Count).All(i=>list.GetItemChecked(i)==initial[i]),"optional mode preserves prior custom selections "+language);list.SetItemChecked(Index(list,"FixMenuSpeed"),false);if(clearAll){for(int i=0;i<list.Items.Count;i++)list.SetItemChecked(i,false);Check(list.CheckedItems.Count==0,"all optional switches can be cleared "+language);}toggled=true;}
 if(!early&&watch.Elapsed.TotalSeconds>=0.5){Check(!yes.Enabled,"confirmation blocked during first second "+language);yes.PerformClick();Check(dialog.Visible,"disabled confirmation cannot close dialog "+language);early=true;}
 if(!captured&&watch.Elapsed.TotalSeconds>=0.6){using(var b=new Bitmap(dialog.Width,dialog.Height)){dialog.DrawToBitmap(b,new Rectangle(Point.Empty,b.Size));b.Save(Path.Combine(output,"review-"+language+".png"),ImageFormat.Png);}captured=true;}
 if(!late&&watch.Elapsed.TotalSeconds>=2.5){Check(!yes.Enabled,"confirmation still blocked before three seconds "+language);late=true;}
 if(watch.Elapsed.TotalSeconds>=3.2&&yes.Enabled){yes.PerformClick();timer.Stop();}
 if(watch.Elapsed.TotalSeconds>8)throw new Exception("Countdown never enabled");
 }catch(Exception ex){failure=ex;foreach(Form d in Application.OpenForms.Cast<Form>().ToList())if(d.Name=="markerInstallReviewDialog")d.DialogResult=DialogResult.No;timer.Stop();}};
 timer.Start();bool result=(bool)Invoke(form,"EnsureMarkerReviewBeforeInstall");timer.Stop();if(failure!=null)throw failure;Check(seen,"first install always opens feature page "+language);if(accept){Check(result&&watch.Elapsed.TotalSeconds>=3,"acceptance requires countdown "+language);Check(!((CheckedListBox)F(form,"markerOptionsList")).GetItemChecked(Index((CheckedListBox)F(form,"markerOptionsList"),"FixMenuSpeed")),"manual option adjustment retained "+language);}else Check(!result,"No returns without installation "+language);return result;}}
 [STAThread]static int Main(string[]a){Console.OutputEncoding=new UTF8Encoding(false);try{return Run(a);}catch(Exception e){Console.WriteLine("FAIL "+e);return 1;}}
 static int Run(string[]a){Application.EnableVisualStyles();asm=Assembly.LoadFrom(a[0]);string output=Path.GetFullPath(a[1]),language=a[2];if(Directory.Exists(output))throw new Exception("Choose a fresh isolated test output directory");Directory.CreateDirectory(output);Call(asm.GetType("L"),"Initialize",language);var engine=asm.GetType("InstallerEngine");var opts=asm.GetType("InstallOptions");var defaults=(Dictionary<string,bool>)Call(engine,"RecommendedMarkerValues");Check(defaults.Count(p=>p.Value)==18,"preset now enables eighteen switches");Check(keys.All(k=>defaults[k]),"six requested defaults are enabled");var full=Activator.CreateInstance(opts,true);opts.GetField("Dlc").SetValue(full,false);opts.GetField("Chinese").SetValue(full,false);opts.GetField("NodeFix").SetValue(full,false);string template=(string)Call(engine,"ReadResourceText","DS2_MARKER_INI");string ini=(string)Call(engine,"ConfigureMarkerPatch",template,full);Check(keys.All(k=>(string)Call(engine,"ReadIniValue",ini,k)=="1"),"full Marker defaults reach actual INI");var minimal=Activator.CreateInstance(opts,true);opts.GetField("MarkerPatch").SetValue(minimal,false);ini=(string)Call(engine,"ConfigureMarkerPatch",template,minimal);Check(keys.All(k=>(string)Call(engine,"ReadIniValue",ini,k)=="0"),"minimal DLC does not enable optional frame fixes");
 using(var form=(Form)Activator.CreateInstance(asm.GetType("InstallerForm"),true)){form.GetType().GetProperty("PreviewOnly",ins).SetValue(form,true,null);string game=Path.Combine(output,"game-a"),other=Path.Combine(output,"game-b");Directory.CreateDirectory(game);Directory.CreateDirectory(other);File.WriteAllText(Path.Combine(game,"deadspace2.exe"),"MZ fake non-running fixture");File.WriteAllText(Path.Combine(other,"deadspace2.exe"),"MZ fake non-running fixture");Invoke(form,"SelectGameDirectory",game);form.Show();Application.DoEvents();Review(form,output,language,true);
 bool unexpected=false;using(var guard=new System.Windows.Forms.Timer {Interval=50}){guard.Tick+=(s,e)=>{var d=Application.OpenForms.Cast<Form>().FirstOrDefault(x=>x.Name=="markerInstallReviewDialog");if(d!=null){unexpected=true;d.DialogResult=DialogResult.No;}};guard.Start();var time=Stopwatch.StartNew();Check((bool)Invoke(form,"EnsureMarkerReviewBeforeInstall")&&!unexpected&&time.Elapsed.TotalSeconds<0.5,"same target reviewed once per session "+language);guard.Stop();}
 ((CheckBox)F(form,"dlcBox")).Checked=false;string empty=Path.Combine(output,"game-empty");Directory.CreateDirectory(empty);File.WriteAllText(Path.Combine(empty,"deadspace2.exe"),"MZ fake non-running fixture");Invoke(form,"SelectGameDirectory",empty);Review(form,output,language,true,true);Check(((CheckedListBox)F(form,"markerOptionsList")).CheckedItems.Count==0,"Yes accepts with no optional switches selected "+language);Invoke(form,"SelectGameDirectory",other);Review(form,output,language,false);Review(form,output,language,false);Check(Directory.GetFiles(game,"*",SearchOption.AllDirectories).Length==1&&Directory.GetFiles(other,"*",SearchOption.AllDirectories).Length==1,"review and cancel do not write installation files "+language);form.Close();}
 File.WriteAllText(Path.Combine(output,"checks-passed.txt"),checks.ToString());Console.WriteLine("ALL MARKER REVIEW CHECKS PASSED "+checks);return 0;}}
